class HorizBalanceWidget
{
    char base[8];
    PanelQuad *meterPQ;
    PanelQuad *arrowPQ;
    PanelQuad *leftKnobPQ;
    PanelQuad *rightKnobPQ;
    PanelQuad *colorLeftPQ;
    PanelQuad *colorRightPQ;
    float meterCenterX;
    bool flashing;

public:
    void SetArrow(float f);
};

void HorizBalanceWidget::SetArrow(float f)
{
    float fp = f, r = 1.0f, g = 1.0f;
    float x, y;

    if (f > 1.0f) f = 1.0f;
    if (f < -1.0f) f = -1.0f;
    if (f < 0.0f) fp = -f;

    arrowPQ->GetCenterPos(x, y);
    arrowPQ->SetCenterPos(x, y);
    arrowPQ->Rotate(meterCenterX, 243, f * 3.14159265358979323846f / 6.0f);

    g = 2 - 2 * fp;
    if (fp < .5f)
    {
        r = 2 * fp;
        g = 1.0f;
    }
    if (f < 0)
    {
        leftKnobPQ->SetColor(r, g, 0, 1.0f);
        rightKnobPQ->SetColor(0, 1.0f, 0, 1.0f);
        flashing = (f > -.05f);
    }
    else
    {
        leftKnobPQ->SetColor(0, 1.0f, 0, 1.0f);
        rightKnobPQ->SetColor(r, g, 0, 1.0f);
        flashing = (f < .05f);
    }
}
